import { customType, text, integer } from "drizzle-orm/sqlite-core";
import { sql } from "drizzle-orm";

// ── D1 (SQLite) column helpers ───────────────────────────────────
// These keep the runtime types the app had with Postgres:
//   timestamps → Date, decimals → string ("123.45"), json → object, booleans → boolean.

/** UUID v4 text primary key, generated by SQLite (works for raw SQL inserts too). */
export const UUID = sql`(lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6))))`;
export const uuidPk = (name = "id") => text(name).primaryKey().default(UUID);

/** ISO-8601 UTC timestamp stored as TEXT (sorts/compares correctly as text). */
const isoTimestamp = customType<{ data: Date; driverData: string }>({
  dataType: () => "text",
  toDriver: (v) => (v instanceof Date ? v : new Date(v as unknown as string)).toISOString(),
  fromDriver: (v) => new Date(v),
});
export const timestamp = (name: string) => isoTimestamp(name);
/** Current time in the same format as Date.toISOString(). */
export const NOW = sql`(strftime('%Y-%m-%dT%H:%M:%fZ','now'))`;
/** created_at / updated_at style column. */
export const timestampNow = (name: string) =>
  isoTimestamp(name).notNull().default(NOW);

/** Money / rates. Stored as REAL, returned as a fixed-scale string like Postgres numeric. */
export const decimal = (name: string, opts: { precision?: number; scale?: number } = {}) => {
  const scale = opts.scale ?? 2;
  return customType<{ data: string; driverData: number }>({
    dataType: () => "numeric",
    toDriver: (v) => Number(v),
    fromDriver: (v) => Number(v).toFixed(scale),
  })(name);
};

/** JSON stored as TEXT. */
export const json = <T = unknown>(name: string) => text(name, { mode: "json" }).$type<T>();

/** Array stored as a JSON text array (Postgres text[] replacement). */
export const textArray = (name: string) =>
  text(name, { mode: "json" }).$type<string[]>().notNull().default(sql`'[]'`);

export const boolean = (name: string) => integer(name, { mode: "boolean" });

/** Postgres `date` replacement: 'YYYY-MM-DD' text. */
export const date = (name: string) => text(name);
